-- Supabase Storage only; private bucket. No public URLs or signed URLs are generated by the application.
begin;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('supplier-invoices','supplier-invoices',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['application/pdf','image/jpeg','image/png'];
-- Restrictive fence also blocks any unrelated permissive Storage policies.
grant execute on function public.supplier_invoice_allowed(boolean) to anon;
create policy supplier_files_fence on storage.objects as restrictive for all to anon,authenticated using(bucket_id<>'supplier-invoices' or public.supplier_invoice_allowed()) with check(bucket_id<>'supplier-invoices' or public.supplier_invoice_allowed());
create policy supplier_files_read on storage.objects for select to authenticated using(bucket_id='supplier-invoices' and public.supplier_invoice_allowed());
create policy supplier_files_insert on storage.objects for insert to authenticated with check(bucket_id='supplier-invoices' and public.supplier_invoice_allowed() and exists(select 1 from public.supplier_invoices i where i.id::text=split_part(name,'/',1)));
create policy supplier_files_delete on storage.objects for delete to authenticated using(bucket_id='supplier-invoices' and public.supplier_invoice_allowed());
commit;
